import itertools

def solve_n_queens(n=9, fixed=None):
    # fixed: dict row->col
    # backtracking
    cols = set()
    diag1 = set()  # r + c
    diag2 = set()  # r - c

    board = [None] * n

    # apply fixed
    if fixed:
        for r, c in fixed.items():
            if c in cols or (r+c) in diag1 or (r-c) in diag2:
                return None
            board[r] = c
            cols.add(c)
            diag1.add(r+c)
            diag2.add(r-c)

    def backtrack(r):
        if r == n:
            return board[:]
        if board[r] is not None:
            return backtrack(r+1)
        for c in range(n):
            if c in cols or (r+c) in diag1 or (r-c) in diag2:
                continue
            board[r] = c
            cols.add(c)
            diag1.add(r+c)
            diag2.add(r-c)
            res = backtrack(r+1)
            if res:
                return res
            board[r] = None
            cols.remove(c)
            diag1.remove(r+c)
            diag2.remove(r-c)
        return None

    return backtrack(0)

sol = solve_n_queens(9, {3: 1})
