def check(board):
    n = len(board)
    for i in range(n):
        for j in range(i+1, n):
            if board[i] == board[j]:
                return False, f"same col {i},{j}"
            if abs(board[i] - board[j]) == abs(i - j):
                return False, f"diag {i},{j}"
    return True, "ok"

